<?php require __DIR__.'/bootstrap.php';require_admin();$stats=['Dealers'=>db()->query('SELECT COUNT(*) FROM users WHERE role="dealer"')->fetchColumn(),'Cars'=>db()->query('SELECT COUNT(*) FROM cars')->fetchColumn(),'Inquiries'=>db()->query('SELECT COUNT(*) FROM inquiries')->fetchColumn()];page_top('Admin dashboard');?><section class="dashboard"><h1>Admin dashboard</h1><div class="grid"><?php foreach($stats as $label=>$value):?><article class="card"><div class="card-body"><p class="muted"><?=e($label)?></p><p class="price"><?=$value?></p></div></article><?php endforeach?></div><p><a class="button" href="add-car.php">Add listing for dealer</a> <a class="button small" href="manage-cars.php">Manage all listings</a></p></section><?php page_bottom();
